"},"contract":"Contract LibraryManagementSystemSystem::renewBook(uid: String,barcode: String): Boolean {
	definition:
		user: User = User.allInstances()->any(u: User|u.UserID = uid),
		copy: BookCopy = BookCopy.allInstances()->any(c: BookCopy|c.Barcode = barcode),
		loan: Loan = Loan.allInstances()->any(l: Loan|l.LoanedUser = user and
